import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import path from 'node:path';
import {foldBranch,stateAt} from 'file:///D:/AI/Story%20Dome/Story/pi-Story/story/packages/core/src/fold/index.ts';
import {schemas,validate} from 'file:///D:/AI/Story%20Dome/Story/pi-Story/story/packages/core/src/schema/index.ts';
import {editorInput} from 'file:///D:/AI/Story%20Dome/Story/pi-Story/story/packages/core/src/flow/inputs.ts';
import {digest} from 'file:///D:/AI/Story%20Dome/Story/pi-Story/story/packages/core/src/shared/text.ts';
const root='D:/AI/Story Dome/Story/pi-Story/story/testing/drafts/DS10-review-defects/v1';
const review=JSON.parse(readFileSync('D:/AI/Story Dome/新版综合方案/测试结果/P2/人工复核/DS10-v1-缺陷复核.json','utf8'));
const chapters=[...new Set(review.items.map(i=>i.chapterId))],variants=[...new Set(review.items.map(i=>i.variantId)),...chapters.map(c=>c+'-control')];
const strings=v=>typeof v==='string'?[v]:v&&typeof v==='object'?Object.values(v).flatMap(strings):[];
let detailsChecked=0,bibleAndLedgerSources=0,intentTargets=0,deathStates=0;
for(const id of variants){const entries=JSON.parse(readFileSync(path.join(root,'acceptance/entries',id+'.json'),'utf8')),text=readFileSync(path.join(root,'acceptance/variants',id+'.md'),'utf8');for(const e of entries){const d=e.details??e.data;if(!d)continue;const name=Object.keys(schemas).find(k=>schemas[k].properties?.schema?.const===d.schema);assert(name);const v=validate(schemas[name],d);assert(v.ok,JSON.stringify(v.errors));detailsChecked++;}const m=foldBranch(entries),draft=m.drafts.at(-1);assert(draft);assert.equal(draft.text,text);assert.equal(draft.digest,digest(text));assert.equal(draft.chapter,m.lastChapter+1);const input=editorInput(m,draft,'full'),all=strings(input);for(const row of review.items.filter(i=>i.variantId===id)){for(const source of row.aiLabel.sources.filter(s=>['bible','ledger'].includes(s.kind))){assert(all.some(s=>s.includes(source.quote)),id+' source '+source.quote);bibleAndLedgerSources++;}if(row.aiLabel.category==='factual_details'){assert(all.some(s=>s.includes(row.aiLabel.original)),id+' missing authoring target');intentTargets++;}for(const source of row.aiLabel.sources.filter(s=>s.kind==='state')){const f=stateAt(m).facts.find(f=>f.id===source.ref);assert(f);assert.equal(JSON.stringify(f.object),source.quote);deathStates++;}}}
const result={variantsChecked:variants.length,currentDraftTextAndDigestMatch:true,priorChapterNumbersMatch:true,detailsChecked,bibleAndLedgerSourcesVerified:bibleAndLedgerSources,factualIntentTargetsVerified:intentTargets,priorDeathStatesVerified:deathStates,modelRequests:0};writeFileSync('D:/开源/test/pi-Story/p2/temp/ds10-review-context-result.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
